ddl_sql:
CREATE TABLE public.feishu_tbl_alpha (
    id BIGSERIAL PRIMARY KEY,
    fields JSONB NOT NULL,
    created_at TIMESTAMP DEFAULT NOW(),
    updated_at TIMESTAMP DEFAULT NOW()
);

-- 飞书多维表同步：消费者事业群任务数据表
CREATE TABLE public.feishu_tbl_alpha
(
  id BIGINT PRIMARY KEY,
  record_id VARCHAR(64) NOT NULL,
  fields JSONB NOT NULL,
  created_time TIMESTAMP(3),
  updated_time TIMESTAMP(3),
  sync_time TIMESTAMP(3)
);
COMMENT ON TABLE public.feishu_tbl_alpha IS '飞书多维表-消费者事业群任务数据（原始表）';
COMMENT ON COLUMN public.feishu_tbl_alpha.id IS '主键ID';
COMMENT ON COLUMN public.feishu_tbl_alpha.record_id IS '飞书记录ID';
COMMENT ON COLUMN public.feishu_tbl_alpha.fields IS '飞书业务JSON字段体';
COMMENT ON COLUMN public.feishu_tbl_alpha.created_time IS '创建时间';
COMMENT ON COLUMN public.feishu_tbl_alpha.updated_time IS '更新时间';
COMMENT ON COLUMN public.feishu_tbl_alpha.sync_time IS '同步时间';
